import os # Bound independent physical verification resources.
os.environ['OPENBLAS_NUM_THREADS']='1' # Leave CPU capacity for concurrent native solves and training.
import json # Save independent mathematical checks and exact input identities.
import numpy as np # Evaluate rigid-motion invariance and variational consistency.
from fem import RUN,REPO,write_json,sha # Reuse original dataset definitions without changing physical labels.
from scipy.sparse import load_npz # Compare independently saved linear operator with nonlinear tangent limit.
from nonlinear_mechanics import FiniteStrain # Inspect actual new finite-strain adapter used in native comparisons.
from dynamic_physics import mass_matrix,newmark # Inspect exact mass integration and actual transient integrator.
from scipy.sparse import csc_matrix # Define a fully specified independent single-degree-of-freedom benchmark.
def main(): # Cross-check newly implemented physics independently of neural accuracy.
    path=RUN/'cases/girder_reference';data=np.load(path/'fields.npz');xyz=data['xyz'];tet=data['tet'];groups=data['groups'];physics=FiniteStrain(xyz,tet,groups,200000.,.3);checks=[] # Use real quadratic mesh and declared steel elasticity.
    angle=np.pi/3;R=np.array([[np.cos(angle),-np.sin(angle),0],[np.sin(angle),np.cos(angle),0],[0,0,1.]]);u=xyz@R.T+np.array([120.,-70.,30.])-xyz;force,info=physics.internal(u);volume=float(data['volume'].sum());scale=200000.*volume/max(np.ptp(xyz,axis=0));relative=float(np.linalg.norm(force)/scale) # Test finite rotation and translation invariance without linearizing the motion.
    checks.append({'name':'finite_rigid_motion','normalized_internal_force':relative,'energy_Nmm':info['energy_Nmm'],'minimum_J':info['min_J'],'pass':relative<1e-12 and abs(info['min_J']-1)<1e-10}) # Require frame-indifferent zero-strain response.
    rng=np.random.default_rng(83);u=.01*xyz;direction=rng.normal(size=xyz.shape);direction/=np.linalg.norm(direction);step=1e-4;force,info=physics.internal(u);_,plus=physics.internal(u+step*direction);_,minus=physics.internal(u-step*direction);numerical=(plus['energy_Nmm']-minus['energy_Nmm'])/(2*step);analytic=float(np.sum(force*direction));error=abs(numerical-analytic)/max(abs(analytic),1.) # Check nonlinear force equals derivative of elastic potential.
    checks.append({'name':'finite_strain_energy_gradient','relative_difference':error,'pass':error<1e-5}) # Use a predeclared finite-difference agreement criterion.
    K=load_npz(path/'stiffness.npz');small=rng.normal(size=xyz.shape)*1e-7;force,_=physics.internal(small);linear=(K@small.ravel()).reshape(-1,3);error=float(np.linalg.norm(force-linear)/max(np.linalg.norm(linear),1e-20)) # Compare small-strain tangent against independently saved linear stiffness.
    checks.append({'name':'linear_tangent_limit','relative_difference':error,'pass':error<1e-5}) # Verify correct stress/strain and shear conventions.
    M,mass=mass_matrix(xyz,tet);translations=np.tile(np.eye(3),(len(xyz),1));effective=translations.T@(M@translations);mass_error=float(np.linalg.norm(effective-mass*np.eye(3))/mass) # Verify total inertial mass in each physical translation direction.
    checks.append({'name':'consistent_mass_conservation','mass_tonne':mass,'relative_difference':mass_error,'pass':mass_error<1e-12}) # Check total mass scaling; this alone cannot distinguish exact integration from mass-conserving underintegration.
    dt=.002;t=np.arange(1001)*dt;load=np.sin(2*np.pi*t);states,v,a,result=newmark(csc_matrix([[100.]]),csc_matrix([[1.]]),np.array([1.]),load,dt);exact=(np.sin(2*np.pi*t)-(2*np.pi/10)*np.sin(10*t))/(100-(2*np.pi)**2);error=float(np.linalg.norm(states[:,0]-exact)/np.linalg.norm(exact)) # Compare zero-initial-state forced oscillator with exact analytical solution.
    balance=a[:,0]+100.*states[:,0]-load;absolute=float(np.max(np.abs(balance)));characteristic=absolute/float(np.max(np.abs(load))) # Audit physical momentum using a fixed force scale so zero-force crossings do not create spurious relative failures.
    checks.append({'name':'newmark_analytical_oscillator','relative_displacement_error':error,'instantaneous_force_normalized_residual':result['max_dynamic_residual'],'absolute_residual_N':absolute,'fixed_peak_force_normalized_residual':characteristic,'energy_balance':result['energy_balance_relative'],'pass':error<.001 and result['energy_balance_relative']<1e-8 and characteristic<1e-8}) # Verify actual integrator mechanics independently of bridge modal truncation and preserve the sensitive diagnostic separately.
    out=REPO/'build/completion-audit-20261024';out.mkdir(exist_ok=True);write_json(out/'physical_invariants.json',{'checks':checks,'source_mesh_sha256':sha(path/'fields.npz'),'status':'PASS' if all(c['pass'] for c in checks) else 'FAIL'});print(json.dumps(checks),flush=True) # Preserve independent evidence without altering any production solver settings.
if __name__=='__main__': main() # Execute all actual invariant checks before final integration.
